INSERT INTO _migration_493_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_reproduction_s2_001', 'topic_igcse_bio_reproduction', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which type of cell division produces two genetically identical daughter cells for growth and repair?', 'multiple_choice', NULL, '["A. Meiosis","B. Fertilisation","C. Mitosis","D. Mutation"]', 'C', 'Mitosis produces two daughter cells with the same chromosome number and identical genes as the parent cell, which is essential for growth and the repair of damaged tissues. Meiosis produces genetically varied gametes, fertilisation is the fusion of gametes rather than a division, and mutation is a change in DNA, not a cell division process. Therefore the correct answer is C: Mitosis.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_reproduction_s2_002', 'topic_igcse_bio_reproduction', 'subj_igcse_biology', 'igcse', NULL, NULL, 'In an insect-pollinated flower, where are the male gametes made?', 'multiple_choice', NULL, '["A. In the stigma","B. In the ovary wall","C. In the sepals","D. In the anthers, inside pollen grains"]', 'D', 'The anthers produce pollen grains, and each pollen grain contains the male gametes. The stigma receives pollen during pollination, the ovary contains the female ovules, and the sepals protect the flower bud, so none of these structures produces male gametes. Therefore the correct answer is D: In the anthers, inside pollen grains.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_reproduction_s2_003', 'topic_igcse_bio_reproduction', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which statement about asexual reproduction is correct?', 'multiple_choice', NULL, '["A. It produces offspring that are genetically identical to the single parent","B. It requires two parents and the fusion of gametes","C. It produces offspring showing wide genetic variation","D. It occurs only in flowering plants"]', 'A', 'Asexual reproduction involves one parent and no fusion of gametes, so the offspring are clones that are genetically identical to the parent. Two parents and gamete fusion describe sexual reproduction, which is also the process that generates wide variation, and asexual reproduction occurs in bacteria, fungi and animals as well as in plants. Therefore the correct answer is A: It produces offspring that are genetically identical to the single parent.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_reproduction_s2_004', 'topic_igcse_bio_reproduction', 'subj_igcse_biology', 'igcse', NULL, NULL, 'After pollination and fertilisation in a flowering plant, which structure develops into a seed?', 'multiple_choice', NULL, '["A. The ovary","B. The ovule","C. The petal","D. The stigma"]', 'B', 'Once the male gamete fuses with the female gamete inside the ovule, the fertilised ovule develops into the seed, while the whole ovary develops into the fruit around it. The ovary forms the fruit rather than the seed, and the petals and stigma wither and die after fertilisation. Therefore the correct answer is B: The ovule.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_reproduction_s2_005', 'topic_igcse_bio_reproduction', 'subj_igcse_biology', 'igcse', NULL, NULL, 'What is one advantage of cross-pollination over self-pollination?', 'multiple_choice', NULL, '["A. It guarantees that every flower is pollinated","B. It does not require wind or insects","C. It increases genetic variation in the offspring","D. It produces offspring identical to the parent"]', 'C', 'Cross-pollination mixes gametes from two different plants, increasing genetic variation and giving the population a better chance of surviving environmental change. Cross-pollination is actually less reliable than self-pollination, still depends on wind or insects, and produces varied offspring rather than identical ones. Therefore the correct answer is C: It increases genetic variation in the offspring.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_reproduction_s2_006', 'topic_igcse_bio_reproduction', 'subj_igcse_biology', 'igcse', NULL, NULL, 'What is the main function of the amniotic fluid that surrounds a developing fetus?', 'multiple_choice', NULL, '["A. It supplies oxygen to the fetus","B. It digests food for the fetus","C. It produces the hormones of pregnancy","D. It cushions and protects the fetus from mechanical damage"]', 'D', 'The amniotic sac and its fluid act as a shock absorber, supporting the fetus and protecting it from bumps and sudden pressure changes. Oxygen and nutrients diffuse across the placenta, the fetus does not digest food before birth, and pregnancy hormones are secreted by the ovary and placenta rather than by the fluid. Therefore the correct answer is D: It cushions and protects the fetus from mechanical damage.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_493_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_493_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_493_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_493_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_493_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_493_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_493_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_493_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_493_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
